.stApp {
    background: #101012;
    color: #f1f1f1;
}

.block-container {
    max-width: 1500px;
    padding-top: 2.5rem;
    padding-bottom: 3rem;
    padding-left: 2.5rem;
    padding-right: 2.5rem;
}

[data-testid="stSidebar"] {
    background: #171719;
    border-right: 1px solid #303034;
}

[data-testid="stSidebar"] h1 {
    color: #ffffff;
    font-size: 28px;
    letter-spacing: 2px;
}

[data-testid="stSidebar"] [role="radiogroup"] label {
    padding: 10px 12px;
    border-radius: 7px;
    transition: background 0.2s;
}

[data-testid="stSidebar"] [role="radiogroup"] label:hover {
    background: #302024;
}

[data-testid="stSidebar"] label:has(input:checked) {
    background: #381d21;
    border-left: 3px solid #c62828;
}

[data-testid="stMetric"] {
    background: linear-gradient(145deg, #232327, #19191c);
    border: 1px solid #36363b;
    border-top: 3px solid #b9252b;
    border-radius: 12px;
    padding: 22px 18px;
    min-height: 125px;
    box-shadow: 0 5px 18px rgba(0,0,0,0.18);
}

[data-testid="stMetricLabel"] {
    color: #b0b0b7;
    font-size: 14px;
}

[data-testid="stMetricValue"] {
    color: #ffffff;
    font-weight: 700;
    font-size: 30px;
}

h1, h2, h3 {
    letter-spacing: -0.5px;
}

.stButton button,
.stDownloadButton button,
[data-testid="stFormSubmitButton"] button {
    border-radius: 8px;
    min-height: 42px;
    font-weight: 600;
}

.stButton button:hover {
    border-color: #e04444;
    color: #e04444;
}

[data-testid="stDataFrame"] {
    border: 1px solid #333338;
    border-radius: 10px;
    overflow: hidden;
}

[data-testid="stPlotlyChart"] {
    background: #151517;
    border: 1px solid #29292e;
    border-radius: 12px;
    padding: 10px;
}

[data-testid="stForm"] {
    background: #171719;
    border: 1px solid #343438;
    border-radius: 12px;
    padding: 24px;
}

[data-baseweb="tab-list"] {
    gap: 15px;
}

[data-baseweb="tab"] {
    padding: 12px 8px;
    font-weight: 600;
}

.dbd-hero {
    position: relative;
    overflow: hidden;
    padding: 48px 38px;
    margin-bottom: 25px;
    border: 1px solid #54262b;
    border-radius: 14px;
    background:
        radial-gradient(ellipse at right, #621c25 0%, transparent 65%),
        linear-gradient(120deg, #171719, #281619);
}

.dbd-hero-label {
    font-size: 11px;
    letter-spacing: 3px;
    color: #e36b6b;
    font-weight: 700;
}

.dbd-hero-title {
    font-size: 52px;
    font-weight: 900;
    letter-spacing: 5px;
    color: #ffffff;
    margin: 12px 0;
}

.dbd-hero-description {
    font-size: 15px;
    color: #b8b8bd;
}

.dbd-hero-line {
    width: 65px;
    height: 3px;
    background: #c62828;
    margin-top: 24px;
}

/* DBD HORROR THEME */

.stApp {
    background:
        radial-gradient(ellipse at 90% 0%,
        #281619 0%, transparent 40%),
        #0c0c0d;
}

.block-container {
    max-width: 1600px;
    padding-top: 2rem;
}

/* 메인 배너 */

.dbd-hero {
    min-height: 290px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    border-radius: 2px;
    border: 1px solid #493334;
    border-bottom: 3px solid #922c2c;
    background:
        linear-gradient(
            90deg,
            rgba(8,8,9,0.97),
            rgba(15,10,12,0.55)
        ),
        radial-gradient(
            ellipse at 80% 70%,
            #743032,
            #171719 60%
        );
}

.dbd-hero-title {
    font-size: 64px;
    font-weight: 900;
    letter-spacing: 9px;
    text-shadow: 3px 3px 15px #000000;
}

.dbd-hero-label {
    color: #b6a3a3;
    letter-spacing: 4px;
}

.dbd-hero-description {
    color: #bdbdbd;
}

.dbd-hero::after {
    content: "ⅠⅠⅠⅠ╱";
    position: absolute;
    right: 8%;
    top: 50%;
    transform: translateY(-50%) rotate(-12deg);
    font-size: 140px;
    font-weight: 900;
    letter-spacing: -10px;
    color: rgba(220,220,220,0.10);
    pointer-events: none;
}

/* 사이드바 */

[data-testid="stSidebar"] {
    background:
        linear-gradient(
            180deg,
            #19191b,
            #0c0c0d
        );
    border-right: 1px solid #493334;
}

[data-testid="stSidebar"] h1 {
    font-size: 30px;
    font-weight: 900;
    letter-spacing: 4px;
}

[data-testid="stSidebar"] [role="radiogroup"] label {
    width: 100%;
    border-radius: 0;
    padding: 12px;
}

[data-testid="stSidebar"] label:has(input:checked) {
    background: linear-gradient(
        90deg, #492124, transparent
    );
    border-left: 3px solid #c33c3c;
}

/* 통계 카드 */

[data-testid="stMetric"] {
    position: relative;
    background: linear-gradient(
        135deg, #242426, #121214
    );
    border: 1px solid #38383a;
    border-left: 3px solid #983333;
    border-top: 1px solid #38383a;
    border-radius: 2px;
    min-height: 135px;
    padding: 24px 20px;
    transition: all 0.2s ease;
}

[data-testid="stMetric"]:hover {
    border-color: #a33a3a;
    background: #25191b;
    transform: translateY(-3px);
}

[data-testid="stMetricValue"] {
    font-size: 36px;
    font-weight: 800;
}

[data-testid="stMetricLabel"] {
    color: #a9a9a9;
}

/* 그래프 및 표 */

[data-testid="stPlotlyChart"],
[data-testid="stDataFrame"],
[data-testid="stForm"] {
    border-radius: 2px;
    border: 1px solid #393536;
    background: #141416;
}

/* 버튼 */

.stButton button,
.stDownloadButton button,
[data-testid="stFormSubmitButton"] button {
    border-radius: 2px;
    letter-spacing: 1px;
}

h1, h2, h3 {
    font-weight: 800;
}

hr {
    border-color: #353031;
}


.dbd-hero {
    background-image:
        linear-gradient(
            90deg,
            rgba(0,0,0,0.92) 0%,
            rgba(0,0,0,0.45) 50%,
            rgba(0,0,0,0.05) 100%
        ),
        url("data:image/jpeg;base64,");
    background-size: cover;
    background-position: center;
    min-height: 320px;
}

.dbd-hero::after {
    display: none;
}

.dbd-hero {
    background-image:
        linear-gradient(
            90deg,
            rgba(0,0,0,0.95) 0%,
            rgba(0,0,0,0.55) 35%,
            rgba(0,0,0,0.05) 100%
        ),
        url("data:image/jpeg;base64,");
    background-size: cover;
    background-position: center 30%;
    min-height: 350px;
    border: 1px solid #454545;
    border-bottom: 3px solid #a32323;
}

.dbd-hero::after {
    display: none;
}

.dbd-hero-title {
    font-size: 64px;
    letter-spacing: 8px;
    text-shadow: 3px 3px 12px #000;
}

.dbd-hero-description {
    color: #dddddd;
}

/* 전체 화면 배경 */

.stApp {
    background-color: #0c0c0d;
    background-image:
        linear-gradient(
            90deg,
            rgba(8,8,10,0.48) 0%,
            rgba(8,8,10,0.92) 23%,
            rgba(8,8,10,0.97) 50%,
            rgba(8,8,10,0.92) 77%,
            rgba(8,8,10,0.48) 100%
        ),
        url("data:image/jpeg;base64,");
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    background-repeat: no-repeat;
}

[data-testid="stAppViewContainer"],
[data-testid="stMain"] {
    background: transparent;
}

[data-testid="stHeader"] {
    background: transparent;
}

.block-container {
    max-width: 1250px;
    padding-top: 4rem;
    padding-bottom: 3rem;
}

/* 기존 이미지 배너 제거 */

.dbd-hero {
    background: transparent;
    border: none;
    min-height: 150px;
    padding: 20px 10px;
    text-align: center;
    align-items: center;
    margin-bottom: 10px;
}

.dbd-hero-title {
    font-size: 58px;
    letter-spacing: 10px;
}

.dbd-hero::after {
    display: none;
}

.dbd-hero-line {
    margin: 20px auto 0;
}

/* 사이드바 */

[data-testid="stSidebar"] {
    background: rgba(12,12,14,0.95);
}

/* 반투명 통계 카드 */

[data-testid="stMetric"] {
    background: rgba(25,25,28,0.85);
    backdrop-filter: blur(8px);
}

[data-testid="stForm"],
[data-testid="stPlotlyChart"],
[data-testid="stDataFrame"] {
    background: rgba(18,18,20,0.90);
    backdrop-filter: blur(6px);
}


/* 사이드바 메뉴 고도화 */

[data-testid="stSidebar"] [data-testid="stRadio"] label {
    width: 100%;
    min-height: 44px;
    padding: 12px 15px;
    margin-bottom: 3px;
    border-left: 3px solid transparent;
    background: transparent;
    transition: all 0.2s ease;
}

[data-testid="stSidebar"] [data-testid="stRadio"] label > div:first-child {
    display: none;
}

[data-testid="stSidebar"] [data-testid="stRadio"] label:has(input:checked) {
    background: linear-gradient(
        90deg, #542327, #211719
    );
    border-left: 3px solid #d63b3b;
}

[data-testid="stSidebar"] [data-testid="stRadio"] label:hover {
    background: #292023;
    border-left-color: #a93232;
}

[data-testid="stSidebar"] [data-testid="stRadio"] label p {
    font-size: 14px;
    font-weight: 600;
}

[data-testid="stSidebar"] {
    background: rgba(10,10,12,0.96);
    backdrop-filter: blur(12px);
}


/* 버튼형 사이드바 메뉴 */

[data-testid="stSidebar"] .stButton button {
    width: 100%;
    min-height: 46px;
    justify-content: flex-start;
    text-align: left;
    padding: 12px 15px;
    border-radius: 3px;
    border: 1px solid transparent;
    background: #171719;
    color: #bdbdbd;
    letter-spacing: 0;
    transition: all 0.2s ease;
}

[data-testid="stSidebar"] .stButton button[kind="primary"] {
    background: linear-gradient(
        90deg, #542327, #241719
    );
    border-left: 3px solid #d33b3b;
    color: #ffffff;
}

[data-testid="stSidebar"] .stButton button:hover {
    background: #342124;
    border-color: #713336;
    color: #ffffff;
}

[data-testid="stSidebar"] .stButton button p {
    font-size: 14px;
    font-weight: 600;
}

[data-testid="stSidebar"] .stButton {
    margin-bottom: -5px;
}

